        .catch((e) => console.error("Mic error:", e));
    } else {
      roomParticipant.setMicrophoneEnabled(false);
    }
  }, [isRecording, room, roomParticipant]);
var sid =!roomParticipant.getTrackPublication(Track.Source.Microphone)? null: roomParticipant.getTrackPublication(Track.Source.Microphone).trackSid
  const transcript = {
    participantIdentities: [useParticipantInfo().identity],
    trackSids: [
      sid
    ],
  };
  const Transcription = () => {
    const transcriptions = useTranscriptions(transcript);
    return (
