  const waveformBars = Array.from({ length: 40 }, (_, i) => ({
    id: i,
    height: Math.random() * 60 + 10,
  }));

  const toggleRecording = () => {
    setIsRecording((prev) => !prev);
  };

  const togglePlayback = () => {
    setIsPlaying((prev) => !prev);
  };

  const toggleAudio = () => {
    setAudio((prev) => !prev);
  };

  return (
    <AudioContainer>
      <SectionHeader>
        <SectionTitle>Audio Processing</SectionTitle>
        <StatusBadge isRecording={isRecording}>
          {isRecording ? "● Recording" : "Standby"}
        </StatusBadge>
      </SectionHeader>

      <AudioVisualization>
        <WaveformContainer>
          {waveformBars.map((bar) => (
            <WaveBar
              key={bar.id}
              isActive={isRecording && bar.id % 3 === 0}
              animate={{
                height: isRecording
                  ? [bar.height, bar.height * 0.3, bar.height]
                  : bar.height * 0.3,
              }}
              transition={{
                duration: 0.8,
                repeat: isRecording ? Infinity : 0,
                delay: bar.id * 0.02,
              }}
            />
          ))}
        </WaveformContainer>
      </AudioVisualization>

