        <ControlButton
          variant="primary"
          onClick={togglePlayback}
          disabled={!isRecording}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {isPlaying ? "⏸" : "▶"}
        </ControlButton>

        <ControlButton whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
